-- 연간 요금제·만료 전 연장 패치 사후 점검. 조회만 수행하며 COMMIT하지 않는다.
SET DEFINE OFF
SELECT '1 yearly plan 12 months 4000' ITEM,CASE WHEN COUNT(*)=1 THEN 'PASS' ELSE 'FAIL' END RESULT FROM SUBSCRIPTION_PLAN WHERE PLAN_CODE='PLAN_YEARLY' AND DURATION_MONTHS=12 AND MONTHLY_UNIT_PRICE=4000 AND USE_YN='Y'
UNION ALL SELECT '2 monthly plan unchanged',CASE WHEN COUNT(*)=1 THEN 'PASS' ELSE 'FAIL' END FROM SUBSCRIPTION_PLAN WHERE PLAN_CODE='PLAN_MONTHLY' AND DURATION_MONTHS=1 AND MONTHLY_UNIT_PRICE=4000 AND USE_YN='Y'
UNION ALL SELECT '3 enabled codes:2',CASE WHEN COUNT(*)=2 THEN 'PASS' ELSE 'FAIL' END FROM COMMON_CODE WHERE CODE IN ('PLAN_YEARLY','PP_RENEW') AND USE_YN='Y';
